    private val FEATURE_INDICES = decodeHexToByteArray(FEATURE_INDICES_HEX)
    private val THRESHOLDS = decodeHexToFloatArray(THRESHOLDS_HEX)
    private val LEFT_CHILDREN = decodeHexToIntArray(LEFT_CHILDREN_HEX)
    private val RIGHT_CHILDREN = decodeHexToIntArray(RIGHT_CHILDREN_HEX)
    private val TREE_OFFSETS = decodeHexToIntArray(TREE_OFFSETS_HEX)
    private val LEAF_PROBABILITIES = decodeHexToFloatArray(LEAF_PROBABILITIES_HEX)

    fun predict(f: SwingFeatures): String {
        val votes = FloatArray(3)
        val features = floatArrayOf(
            f.s1_gyro_y_std, f.s1_gyro_z_std, f.s1_deltaX, f.s1_deltaZ,
            f.s2_gyroMag, f.s2_grav_y_mean, f.s2_deltaX, f.s2_deltaZ,
            f.s3_rollImpactDeg, f.s3_yawImpactDeg, f.s3_deltaX, f.s3_deltaZ,
            f.s3_planeRatio, f.s3_gyro_y_min
        )

        for (t in 0 until NUM_TREES) {
            var nodeIdx = TREE_OFFSETS[t]
            while (true) {
                val feat = FEATURE_INDICES[nodeIdx].toInt()
                if (feat == -1 || feat == 255) {
                    val probIdx = LEFT_CHILDREN[nodeIdx] * 3
                    for (c in 0 until 3) {
                        votes[c] += LEAF_PROBABILITIES[probIdx + c]
                    }
                    break
                }
                val valToCompare = features[feat]
                val threshold = THRESHOLDS[nodeIdx]
                nodeIdx = if (valToCompare <= threshold) {
                    LEFT_CHILDREN[nodeIdx]
                } else {
                    RIGHT_CHILDREN[nodeIdx]
                }
            }
        }

        var maxVal = -1f
        var maxIdx = 0
        for (i in 0 until 3) {
            if (votes[i] > maxVal) {
                maxVal = votes[i]
                maxIdx = i
            }
        }
        return CLASSES[maxIdx]
    }

    private fun decodeHexToByteArray(hexStrings: Array<String>): ByteArray {
        val totalLength = hexStrings.sumOf { it.length } / 2
        val result = ByteArray(totalLength)
        var outIdx = 0
        for (s in hexStrings) {
            var i = 0
            while (i < s.length) {
                val high = Character.digit(s[i], 16)
                val low = Character.digit(s[i + 1], 16)
                result[outIdx++] = ((high shl 4) or low).toByte()
                i += 2
            }
        }
        return result
    }

    private fun decodeHexToFloatArray(hexStrings: Array<String>): FloatArray {
        val bytes = decodeHexToByteArray(hexStrings)
        val buffer = ByteBuffer.wrap(bytes).order(ByteOrder.BIG_ENDIAN)
        val result = FloatArray(bytes.size / 4)
        for (i in result.indices) {
            result[i] = buffer.float
        }
        return result
    }

    private fun decodeHexToIntArray(hexStrings: Array<String>): IntArray {
        val bytes = decodeHexToByteArray(hexStrings)
        val buffer = ByteBuffer.wrap(bytes).order(ByteOrder.BIG_ENDIAN)
        val result = IntArray(bytes.size / 4)
        for (i in result.indices) {
            result[i] = buffer.int
        }
        return result
    }
